     * Swift or Kotlin reference gives no guarantee the key bytes leave memory (spec 11.3).
     */
    func lock() 
    
    func put(recordId: String, plaintext: Data) throws 
    
    func securityInfo() throws  -> FfiSecurityInfo
    
    func state()  -> FfiVaultState
    
    /**
     * Primary path: one OS biometric prompt, cached material, works offline.
     */
