/**
 * The error taxonomy as the host sees it (spec 7.4).
 *
 * Hosts implementing a provider throw one of these. Anything else a foreign implementation
 * raises arrives as [`FfiVaultError::Unexpected`], which the adapter maps to `Unavailable` -
 * retryable and uncounted, because a flaky network must never look like a failed
 * authentication.
 */
public 
enum FfiVaultError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * User dismissed a prompt. Normal; not counted toward lockout.
     */
    case Cancelled
    /**
     * Offline, backend down, or a callback that blew its deadline. Retryable; not counted.
     */
    case Unavailable
    /**
     * Verification genuinely failed. The only case that counts toward lockout.
     */
    case Denied
    /**
     * Integrator bug. Surfaced loudly; not counted.
     */
    case Misconfigured(detail: String
    )
    /**
     * `getKeyMaterial` returned different bytes than at enrollment. Caught by a key check
     * value before any ciphertext was read.
     */
    case ProviderMaterialMismatch(detail: String
    )
    /**
     * The provider rotated its key id. Expected; drive `unlockWithRecovery` to rewrap.
     */
    case ProviderKeyRotated(detail: String
    )
    /**
     * Material failed the enrollment sanity checks.
     */
    case MaterialRejected(detail: String
    )
    /**
     * Stored data is corrupt or was tampered with.
     */
    case CorruptData(detail: String
    )
    /**
     * Anything a foreign implementation raised that is not one of the above.
     */
    case Unexpected(detail: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

