@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiVaultError: FfiConverterRustBuffer {
    typealias SwiftType = FfiVaultError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiVaultError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Cancelled
        case 2: return .Unavailable
        case 3: return .Denied
        case 4: return .Misconfigured(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 5: return .ProviderMaterialMismatch(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 6: return .ProviderKeyRotated(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 7: return .MaterialRejected(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 8: return .CorruptData(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 9: return .Unexpected(
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiVaultError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .Cancelled:
            writeInt(&buf, Int32(1))
        
        
        case .Unavailable:
            writeInt(&buf, Int32(2))
        
        
        case .Denied:
            writeInt(&buf, Int32(3))
        
        
        case let .Misconfigured(detail):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .ProviderMaterialMismatch(detail):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .ProviderKeyRotated(detail):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .MaterialRejected(detail):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .CorruptData(detail):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Unexpected(detail):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(detail, into: &buf)
            
        }
    }
}


