private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variable to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private let initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 30
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_envelock_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_envelock_checksum_func_default_config() != 28959) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_envelock_checksum_func_scheme_version() != 3406) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_envelock_checksum_method_enclavekeystoreffi_create_key() != 52154) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_envelock_checksum_method_enclavekeystoreffi_device_secret() != 277) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_envelock_checksum_method_enclavekeystoreffi_key_exists() != 24443) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_envelock_checksum_method_enclavekeystoreffi_delete_key() != 23327) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_envelock_checksum_method_enclavekeystoreffi_hardware_backing() != 8846) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_envelock_checksum_method_ffivault_change_recovery_factor() != 31139) {
